// Level: Yeonseo central district (fictional) — the planned large city prepared for the later Yeonseo
// missions (M10 HOMECOMING, M15 RECLAIM). Not used by M02, which keeps its own avenue (YeonseoCity.js).
// Generated by world/city/Yeonseo.js: road network → zones → parcels → buildings → streetscape → vehicles,
// then validated (overlaps, road intrusion, ground contact, floating, zone fit, entrance access).
// After build(): this.plan (the registry), this.report (validation result, also window.__cityReport).
import * as THREE from 'three';
import { pbr } from '../../render/TextureFactory.js';
import { Sky } from '../../render/Sky.js';
import { settings } from '../../core/Settings.js';
import { buildYeonseo, LAYOUT } from '../city/Yeonseo.js';
import { Rect } from '../city/CityPlan.js';

const V = (x, y, z) => new THREE.Vector3(x, y, z);
export const METRO = { bounds: { minX: -60, maxX: 60, minZ: -225, maxZ: 222 }, layout: LAYOUT };

export class YeonseoMetro {
  // opts: { corridors: [{ rect: Rect, why }] scripted vehicle routes to keep clear, jam: bool, bounds }
  constructor(game, opts = {}) { this.game = game; this.opts = opts; }
  async build() {
    const g = this.game, w = g.world;
    w.bounds = { ...(this.opts.bounds || METRO.bounds) };
    this.atmosphere();
    const city = buildYeonseo(g, { corridors: this.opts.corridors || [], jam: !!this.opts.jam, early: (ctx) => this.buildOverpass(165, ctx) });
    this.city = city; this.plan = city.plan; this.report = city.report; this.kit = city.kit; this.hf = w.heightFn;
  }
  atmosphere() {
    const g = this.game, scene = g.renderer.scene;
    scene.fog = new THREE.FogExp2(0x8c8a84, 0.0105);
    scene.environment = g.renderer.envMap; scene.environmentIntensity = 0.45;
    this.sky = new Sky(scene, { zenith: 0x6d747c, horizon: 0xa9a49a, stars: 0, sunDir: [-0.3, 0.45, 0.6], sunColor: 0xd8d0c0, sunSize: 0.9996 });
    this.hemi = new THREE.HemisphereLight(0xb4b8bc, 0x5a554c, 1.25); scene.add(this.hemi);
    const sun = new THREE.DirectionalLight(0xe8dcc8, 1.6); const sh = settings.data.graphics.shadows;
    sun.castShadow = sh !== 'off'; const size = { medium: 1024, high: 2048, ultra: 4096 }[sh] || 1024;
    sun.shadow.mapSize.set(size, size); Object.assign(sun.shadow.camera, { left: -55, right: 55, top: 55, bottom: -55, near: 1, far: 260 }); sun.shadow.bias = -0.0004; sun.shadow.normalBias = 0.03;
    scene.add(sun); scene.add(sun.target); g.sun = sun; g.sunOffset = V(-45, 80, 60); this.sunLight = sun;
    g.renderer.renderer.toneMappingExposure = 1.0;
    g.effects.setSmokeLight(0.85);
  }
  buildOverpass(z, ctx) {
    const g = this.game, scene = g.renderer.scene, conc = pbr('concrete', { color: 0x9c9a92, key: 'overpass' }), plan = ctx.plan;
    this.overpass = { z, spans: [] };
    for (const [x0, x1] of [[-190, -9], [-9, 9], [9, 190]]) {
      const span = new THREE.Group(); span.position.set((x0 + x1) / 2, 7.6, z); span.userData.dynamic = true; scene.add(span);
      const deck = new THREE.Mesh(new THREE.BoxGeometry(x1 - x0, 1.2, 12), conc); deck.castShadow = true; deck.receiveShadow = true; span.add(deck);
      for (const s of [-1, 1]) { const rail = new THREE.Mesh(new THREE.BoxGeometry(x1 - x0, 1.0, 0.3), conc); rail.position.set(0, 1.1, s * 5.85); span.add(rail);
        const girder = new THREE.Mesh(new THREE.BoxGeometry(x1 - x0, 0.9, 0.5), conc); girder.position.set(0, -1.05, s * 3.6); span.add(girder); }
      this.overpass.spans.push(span);
      plan.add({ kind: 'structure', id: `overpass${x0}`, rect: new Rect(x0, z - 6, x1, z + 6), y0: 7.0, h: 1.2, obj: span, tags: ['elevated', 'onRoad'] });
    }
    // piers with a cap beam (on land inside the band)
    for (const x of [-160, -130, -100, -76, -56, -36, -18, 18, 36, 56, 76, 100, 130, 160]) {
      const y0 = ctx.ground(x, z); const rect = Rect.c(x, z, 1.6, 2.4); if (!plan.free(rect, { reserved: false })) continue;
      const p = g.props.box(V(1.6, 6.05 - y0, 2.4), V(x, y0 + (6.05 - y0) / 2, z), conc, { surface: 'concrete' });
      const cap = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.9, 11), conc); cap.position.set(x, 6.5, z); cap.castShadow = true; scene.add(cap);
      plan.add({ kind: 'structure', id: `pier${x}`, rect, y0, h: 6.05 - y0, obj: p, colliders: [p.userData.collider] });
    }
  }
  update(dt) { this.sky.update(dt, this.game.renderer.camera); }
}
